        '<button type="button" class="_eli3_ae_btn" id="_eli3_ae_open">' +
          '<span class="_eli3_ae_btn_icon">🚀</span>' +
          '<span class="_eli3_ae_btn_label">Open Gmail Draft</span>' +
        '</button>' +
      '</div>' +
    '</div>';

  root.querySelector("._eli3_ae_back").onclick = onBack;
  root.querySelector("#_eli3_ae_home").onclick = onBack;

  var entitySel = root.querySelector("#_eli3_ae_entity");
  var typeSel   = root.querySelector("#_eli3_ae_type");
  var tpEntInp  = root.querySelector("#_eli3_ae_tpentity");
  var tpContact = root.querySelector("#_eli3_ae_tpcontact");
  var tpNameInp = root.querySelector("#_eli3_ae_tpname");
  var tpEmailInp= root.querySelector("#_eli3_ae_tpemail");
  var reqSel    = root.querySelector("#_eli3_ae_req_sel");
  var reqManual = root.querySelector("#_eli3_ae_req_manual");
  var reqNameInp= root.querySelector("#_eli3_ae_req_name");
  var reqEmailInp= root.querySelector("#_eli3_ae_req_email");
  var ccsInp    = root.querySelector("#_eli3_ae_ccs");
  var refInp    = root.querySelector("#_eli3_ae_ref");

  // Pre-select the agreement type dropdown via fuzzy match (engine helper).
  var rawType = prefill.type || prefill.agreement_type || "";
  if (rawType && typeSel.options.length) {
    var optTexts = [];
    for (var i = 0; i < typeSel.options.length; i++) optTexts.push(typeSel.options[i].text);
    var idx = matchAgTypeIndex(rawType, optTexts);
    if (idx !== -1) typeSel.selectedIndex = idx;
  }
  // Pre-select requester by name. FROM v2 line 20475.
  if (prefill.requester_name && reqSel) {
    var found = false;
    for (var ri = 0; ri < reqSel.options.length; ri++) {
      if (reqSel.options[ri].text.toLowerCase() === String(prefill.requester_name).toLowerCase()) {
        reqSel.selectedIndex = ri; found = true; break;
      }
    }
    if (!found) {
      reqSel.value = "add_other";
      reqManual.style.display = "";
      reqNameInp.value = prefill.requester_name;
      if (prefill.requester_email) reqEmailInp.value = prefill.requester_email;
    }
  }

  // Toggle TP-contact section.
  Array.prototype.forEach.call(root.querySelectorAll('input[name="_eli3_ae_dest"]'), function (rb) {
    rb.onchange = function () { tpContact.style.display = rb.value === "tp" ? "" : "none"; };
  });
  reqSel.onchange = function () {
    var addOther = reqSel.value === "add_other";
    reqManual.style.display = addOther ? "" : "none";
  };
  // FROM v2 line 20566 — Add Participants toggle reveals the green box
  // and hides itself.
  var addCcToggle = root.querySelector("#_eli3_ae_addcc_toggle");
  var addCcBox = root.querySelector("#_eli3_ae_addcc_box");
  if (addCcToggle && addCcBox) {
    addCcToggle.onclick = function () {
      addCcBox.style.display = "";
      addCcToggle.style.display = "none";
    };
  }

  root.querySelector("#_eli3_ae_req_save").onclick = function () {
    var name = reqNameInp.value.trim();
    var email = reqEmailInp.value.trim();
    if (!name || !email) { if (typeof showToast === "function") showToast("⚠️ Enter name + email first", "warn"); return; }
    onSaveRequester({ name: name, email: email });
  };
  root.querySelector("#_eli3_ae_req_use").onclick = function () {
    reqManual.style.display = "none";
  };
  // Strip-prefill button — wipe doc settings; init re-renders with
  // empty prefill so all fields clear in one shot. Toast only on real
  // success; reject path surfaces an error toast.
  var stripBtn = root.querySelector("#_eli3_ae_strip_prefill");
  if (stripBtn) {
    stripBtn.onclick = function () {
      stripBtn.disabled = true;
      Promise.resolve(onStripPrefill()).then(function () {
        // Re-render handles field clear; toast for confirmation.
        if (typeof showToast === "function") showToast("✓ Emailer prefill removed from document", "ok");
      }).catch(function (err) {
        stripBtn.disabled = false;
        if (typeof showToast === "function") {
          showToast("Couldn't strip prefill: " + (err && err.message || "unknown"), "err");
        }
      });
    };
  }
  root.querySelector("#_eli3_ae_req_del").onclick = function (e) {
    e.preventDefault();
    var id = reqSel.value;
    if (!id || id === "add_other") { if (typeof showToast === "function") showToast("Select a saved name first", "warn"); return; }
    onDeleteRequester(id);
  };

  var openBtn = root.querySelector("#_eli3_ae_open");
  openBtn.onclick = function () {
    var dest = (root.querySelector('input[name="_eli3_ae_dest"]:checked') || {}).value || "tp";
    var entity = entitySel.value;
    var type = typeSel.value;
    var tpEntity = tpEntInp.value.trim();
    var tpName = tpNameInp.value.trim();
    var tpEmail = tpEmailInp.value.trim();
    var reqName = "", reqEmail = "";
    if (reqSel.value === "add_other" || reqSel.value === "") {
      reqName = reqNameInp.value.trim();
      reqEmail = reqEmailInp.value.trim();
    } else {
      var opt = reqSel.options[reqSel.selectedIndex];
      reqName = (opt && opt.text) || "";
      reqEmail = (opt && opt.dataset && opt.dataset.email) || "";
    }
    var ccs = ccsInp.value || "";
    var cpRef = refInp.value.trim();

    onPersistPrefill({
      colgate_entity: entity,
      type: type,
      agreement_type: type,
      third_party_entity: tpEntity,
      contact_full_name: tpName,
      contact_email: tpEmail,
      cp_ref: cpRef,
    });

    openBtn.disabled = true;
    var origLabel = openBtn.querySelector("._eli3_ae_btn_label");
    var prev = origLabel.textContent;
    origLabel.textContent = "Opening…";
    Promise.resolve(onOpenGmail({
      dest: dest,
      entity: entity,
      type: type,
      third_party_entity: tpEntity,
      contact_full_name: tpName,
      contact_email: tpEmail,
      requester_name: reqName,
      requester_email: reqEmail,
      cp_ref: cpRef,
      additional_ccs: ccs,
    })).then(function () {
      setTimeout(function () {
        openBtn.disabled = false;
        origLabel.textContent = prev;
      }, 1500);
    }).catch(function () {
      openBtn.disabled = false;
      origLabel.textContent = prev;
    });
  };

  mount.appendChild(root);
}

// renderTemplatesPanel — FROM v2 showConfigModal('email') (line 13833+).
