view.renderTemplatesPanel:
function renderTemplatesPanel(opts) {
  var mount = opts.mount || document.getElementById("_eli3_dashboard_root");
  if (!mount) return;
  var initial = opts.templates || { myName: "", useFullName: false, thirdParty: {subject:"",body:""}, requester: {subject:"",body:""}, byType: {} };
  var agTypes = opts.agTypes || [];
  var onBack = opts.onBack || function () {};
  var onSave = opts.onSave || function () {};

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }

  // Working cache — same pattern as v2's _editCache. __default holds the
  // top-level thirdParty/requester; per-type overrides keyed by type.
  var cache = { __default: {
    thirdParty: { subject: initial.thirdParty.subject || "", body: initial.thirdParty.body || "" },
    requester:  { subject: initial.requester.subject  || "", body: initial.requester.body  || "" },
  } };
  Object.keys(initial.byType || {}).forEach(function (k) {
    var v = initial.byType[k];
    cache[k] = {
      thirdParty: { subject: (v.thirdParty || {}).subject || "", body: (v.thirdParty || {}).body || "" },
      requester:  { subject: (v.requester  || {}).subject || "", body: (v.requester  || {}).body || "" },
    };
  });

  var typeOpts = '<option value="__default">Default (all types)</option>' +
    agTypes.map(function (t) { return '<option value="' + _esc(t) + '">' + _esc(t) + '</option>'; }).join("");

  mount.innerHTML = "";
  var root = document.createElement("div");
  root.className = "_eli3_ae_root _eli3_ae_tmpl_root";
  root.innerHTML =
    '<div class="_eli3_ae_bar">' +
      '<button class="_eli3_ae_back">←</button>' +
      '<div class="_eli3_ae_title">⚙️ Email Templates</div>' +
    '</div>' +
    '<div class="_eli3_ae_form">' +
      '<label class="_eli3_ae_label">My Name <span class="_eli3_ae_hint">(used for [My Name] token)</span></label>' +
      '<input type="text" class="_eli3_ae_input" id="_eli3_ae_tmpl_myname" value="' + _esc(initial.myName || "") + '">' +
      '<label class="_eli3_ae_dest_opt" style="margin-top:6px;">' +
        '<input type="checkbox" id="_eli3_ae_tmpl_useFull"' + (initial.useFullName ? " checked" : "") + '>' +
        '<span>Use full name in signature</span>' +
      '</label>' +
      '<div class="_eli3_ae_tmpl_typebox">' +
        '<label class="_eli3_ae_label" style="color:#92400e;margin-top:0;">Agreement Type Template</label>' +
        '<select class="_eli3_ae_input" id="_eli3_ae_tmpl_type">' + typeOpts + '</select>' +
        '<div class="_eli3_ae_tmpl_hint" id="_eli3_ae_tmpl_hint">Editing the default template used for all agreement types.</div>' +
      '</div>' +
      '<div class="_eli3_ae_tmpl_block _eli3_ae_tmpl_block_tp">' +
        '<div class="_eli3_ae_tmpl_block_head">TO: THIRD PARTY (External)</div>' +
        '<label class="_eli3_ae_label">Subject</label>' +
        '<input type="text" class="_eli3_ae_input" id="_eli3_ae_tmpl_subj_tp">' +
        '<label class="_eli3_ae_label">Body</label>' +
        '<textarea class="_eli3_ae_input _eli3_ae_tmpl_textarea" id="_eli3_ae_tmpl_body_tp"></textarea>' +
      '</div>' +
      '<div class="_eli3_ae_tmpl_block _eli3_ae_tmpl_block_req">' +
        '<div class="_eli3_ae_tmpl_block_head">TO: REQUESTER (Internal)</div>' +
        '<label class="_eli3_ae_label">Subject</label>' +
        '<input type="text" class="_eli3_ae_input" id="_eli3_ae_tmpl_subj_req">' +
        '<label class="_eli3_ae_label">Body</label>' +
        '<textarea class="_eli3_ae_input _eli3_ae_tmpl_textarea" id="_eli3_ae_tmpl_body_req"></textarea>' +
      '</div>' +
      '<div class="_eli3_ae_tmpl_resetrow">' +
        '<button type="button" class="_eli3_ae_skip _eli3_ae_tmpl_reset" id="_eli3_ae_tmpl_reset" style="display:none;">↩ Reset to default</button>' +
      '</div>' +
      '<div class="_eli3_ae_tmpl_tokens">' +
        'Available tokens: [Entity], [TP Entity], [Type], [CP Ref], [Date], [TP Contact], [Requester], [My Name], [Protocol]' +
      '</div>' +
      '<div class="_eli3_ae_actions">' +
        '<button type="button" class="_eli3_ae_skip" id="_eli3_ae_tmpl_cancel">Cancel</button>' +
        '<button type="button" class="_eli3_ae_btn" id="_eli3_ae_tmpl_save">' +
          '<span class="_eli3_ae_btn_icon">💾</span>' +
          '<span class="_eli3_ae_btn_label">Save settings</span>' +
        '</button>' +
      '</div>' +
    '</div>';
  root.querySelector("._eli3_ae_back").onclick = onBack;
  root.querySelector("#_eli3_ae_tmpl_cancel").onclick = onBack;

  var typeSel = root.querySelector("#_eli3_ae_tmpl_type");
  var hintEl  = root.querySelector("#_eli3_ae_tmpl_hint");
  var resetBtn= root.querySelector("#_eli3_ae_tmpl_reset");
  var subjTp  = root.querySelector("#_eli3_ae_tmpl_subj_tp");
  var bodyTp  = root.querySelector("#_eli3_ae_tmpl_body_tp");
  var subjReq = root.querySelector("#_eli3_ae_tmpl_subj_req");
  var bodyReq = root.querySelector("#_eli3_ae_tmpl_body_req");
  var prev = "__default";

  function _stash(key) {
    cache[key] = {
      thirdParty: { subject: subjTp.value, body: bodyTp.value },
      requester:  { subject: subjReq.value, body: bodyReq.value },
    };
  }
  function _load(key) {
    var src = cache[key] || cache.__default;
    subjTp.value  = src.thirdParty.subject || "";
    bodyTp.value  = src.thirdParty.body    || "";
    subjReq.value = src.requester.subject  || "";
    bodyReq.value = src.requester.body     || "";
    if (key === "__default") {
      hintEl.textContent = "Editing the default template used for all agreement types.";
      resetBtn.style.display = "none";
    } else {
      hintEl.textContent = cache[key]
        ? "Custom template for “" + key + "”."
        : "Using default template. Edit to customize for this type.";
      resetBtn.style.display = cache[key] ? "" : "none";
    }
  }
  _load("__default");

  typeSel.onchange = function () {
    _stash(prev);
    prev = typeSel.value;
    _load(prev);
  };
  resetBtn.onclick = function () {
    delete cache[typeSel.value];
    _load(typeSel.value);
  };

  root.querySelector("#_eli3_ae_tmpl_save").onclick = function () {
    _stash(prev);
    var byType = {};
    Object.keys(cache).forEach(function (k) {
      if (k !== "__default") byType[k] = cache[k];
    });
    onSave({
      myName: root.querySelector("#_eli3_ae_tmpl_myname").value.trim(),
      useFullName: root.querySelector("#_eli3_ae_tmpl_useFull").checked,
      thirdParty: cache.__default.thirdParty,
      requester:  cache.__default.requester,
      byType: byType,
    });
  };

  mount.appendChild(root);
}

jsonTools.init:
function init(eli) {
  if (!eli.events) eli.events = { guard: function (fn) { return fn; }, safeAsync: function (p) { return p; } };
  var bundle = eli.tools._loaded["auto_emailer"];
  if (!bundle) return;
  var renderComposer = bundle._eliViewFns && bundle._eliViewFns.renderComposer;
  var renderTemplatesPanel = bundle._eliViewFns && bundle._eliViewFns.renderTemplatesPanel;
  var shapeEmailTemplates = bundle._eliEngineFns && bundle._eliEngineFns.shapeEmailTemplates;
  var buildGmailUrl = bundle._eliEngineFns && bundle._eliEngineFns.buildGmailUrl;
  var matchAgTypeIndex = bundle._eliEngineFns && bundle._eliEngineFns.matchAgTypeIndex;
  var cleanAiPrefill = bundle._eliEngineFns && bundle._eliEngineFns.cleanAiPrefill;
  var formatParticipantsCcs = bundle._eliEngineFns && bundle._eliEngineFns.formatParticipantsCcs;
  var extractProtocol = bundle._eliEngineFns && bundle._eliEngineFns.extractProtocol;

  if (!renderComposer || !shapeEmailTemplates || !buildGmailUrl) {
    eli.log.event("tool", "auto_emailer_load_failed", {
      hasView: !!renderComposer,
      hasShape: !!shapeEmailTemplates,
      hasBuildUrl: !!buildGmailUrl,
    });
    return;
  }

  function _recordStatSafe(name) {
    try {
      if (eli.stats && typeof eli.stats.record === "function") eli.stats.record(name);
    } catch (e) {
      eli.log.event("tool", "auto_emailer_stat_failed", { stat: name, msg: e && e.message });
    }
  }

  // FROM v2 line 20290 — persist user-edited values back to doc settings
  // so the next emailer open (any user, any machine) skips AI roundtrip.
  function _persistDocPrefill(patch) {
    if (!patch) return;
    try {
      var s = Office.context.document.settings;
      var current = s.get("EliEmailerPrefill") || {};
      Object.keys(patch).forEach(function (k) {
        if (patch[k] == null || patch[k] === "") delete current[k];
        else current[k] = patch[k];
      });
      s.set("EliEmailerPrefill", current);
      if (typeof s.saveAsync === "function") {
        s.saveAsync(function (res) {
          if (res && res.status !== Office.AsyncResultStatus.Succeeded) {
            eli.log.event("tool", "auto_emailer_persist_failed", { msg: res.error && res.error.message });
          }
        });
      }
    } catch (e) {
      eli.log.event("tool", "auto_emailer_persist_threw", { msg: e && e.message });
    }
  }

  function _readDocPrefill() {
    try {
      var cached = Office.context.document.settings.get("EliEmailerPrefill");
      if (cached && typeof cached === "object") return cached;
    } catch (e) { /* tolerate */ }
    return {};
  }

  // FROM v2 line 20265-20282 — OARS-priority agreement type. The user
  // explicitly chose a type at OARS load time (persisted to doc settings
  // as AgreementDataDetails.type); that wins over whatever the AI sniffed.
  // Returns "" if no OARS type is set.
  function _readOarsAgreementType() {
    try {
      var details = Office.context.document.settings.get("AgreementDataDetails");
      if (details && typeof details.type === "string") {
        var t = details.type.trim();
        if (t && t.toLowerCase() !== "local") return t;
      }
    } catch (e) { /* tolerate */ }
    return "";
  }

  // 2026-05-27: comprehensive OARS prefill. Mirrors the priority-aware
  // label matcher build_draft uses (_extractOarsMetadata). Returns ONLY
  // the fields OARS could populate; empty string for the rest. Caller
  // merges into prefillBase, then the AI body scan only runs if both
  // OARS AND the doc-settings fallback failed.
  function _readOarsPrefill() {
    var out = {
      type: "", colgate_entity: "", third_party_entity: "",
      contact_full_name: "", contact_email: "",
      requester_name: "", requester_email: "",
      cp_ref: "",
    };

    // Explicit type from doc settings (the user picked it at OARS load
    // time). Highest authority.
    try {
      var explicit = _readOarsAgreementType();
      if (explicit) out.type = explicit;
    } catch (_e) {}

    var oarsState = null;
    try {
      if (eli.dispatch && typeof eli.dispatch === "function") {
        oarsState = eli.dispatch("oars", "getState");
      }
    } catch (_e) {}
    if (!oarsState) return out;

    // Strip trailing parentheticals so labels like "Third Party Name
    // (Contracting Entity)" still match the base-form regexes.
    function _normLabel(s) {
      return String(s || "").replace(/\s*\([^)]*\)\s*$/, "").trim();
    }

    // [outKey, regex, priority]. Higher priority wins per key.
    var specs = [
      ["requester_name",     /^\s*(?:requester|requestor)\s+name\s*$/i, 20],
      ["requester_name",     /^\s*(?:requester|requestor)\s*$/i, 10],
      ["requester_email",    /^\s*(?:requester|requestor)(?:\s+|s\s+)?(?:e[\s-]?mail|email|email address)\s*$/i, 10],
      ["colgate_entity",     /^\s*(?:colgate|cp|hpn|hill(?:'s|s)?)\s+entity\s*$/i, 10],
      // Third party precedence: Name > Entity > Company > bare > Counterparty.
      ["third_party_entity", /^\s*third[\s-]?party\s+name\s*$/i, 40],
      ["third_party_entity", /^\s*third[\s-]?party\s+entity\s*$/i, 30],
      ["third_party_entity", /^\s*third[\s-]?party\s+company\s*$/i, 25],
      ["third_party_entity", /^\s*third[\s-]?party\s*$/i, 20],
      ["third_party_entity", /^\s*counterparty\s+name\s*$/i, 15],
      ["third_party_entity", /^\s*counterparty\s*$/i, 10],
      // Contact person at the third party (signature-block recipient).
      ["contact_full_name",  /^\s*(?:third[\s-]?party|counterparty|vendor|supplier)\s+contact(?:\s+name)?\s*$/i, 20],
      ["contact_full_name",  /^\s*contact(?:\s+(?:name|person|full\s+name))?\s*$/i, 10],
      ["contact_email",      /^\s*(?:third[\s-]?party|counterparty|vendor|supplier|contact)\s+(?:e[\s-]?mail|email|email address)\s*$/i, 20],
      ["contact_email",      /^\s*(?:e[\s-]?mail|email|email address)\s*$/i, 10],
      ["cp_ref",             /^\s*(?:cp[\s-]?ref(?:erence)?(?:\s*#)?|ref(?:erence)?(?:\s*#)?|a[\s-]?number|agreement\s+request\s+number)\s*$/i, 10],
      ["type",               /^\s*(?:agreement\s+type|type\s+of\s+agreement|type)\s*$/i, 5],
    ];

    var bestPriority = {};
    if (out.type) bestPriority.type = 100; // doc-settings explicit type is sacred
    function _set(key, val, priority) {
      if (!val) return;
      var v = String(val).trim();
      if (!v) return;
      if (bestPriority[key] == null || priority > bestPriority[key]) {
        out[key] = v;
        bestPriority[key] = priority;
      }
    }

    if (oarsState.tablesData && oarsState.tablesData.length) {
      oarsState.tablesData.forEach(function (table) {
        if (!table || !table.length) return;
        table.forEach(function (row) {
          if (!row || row.length < 2) return;
          var k = _normLabel(row[0]);
          specs.forEach(function (s) {
            if (s[1].test(k)) _set(s[0], row[1], s[2]);
          });
        });
      });
    }
    if (oarsState.text) {
      var lines = String(oarsState.text).split(/\r?\n/);
      lines.forEach(function (ln) {
        var m = ln.match(/^\s*(.+?)\s*[:=]\s*(.+?)\s*$/);
        if (!m) return;
        var key = _normLabel(m[1]), val = m[2];
        specs.forEach(function (s) {
          if (s[1].test(key)) _set(s[0], val, s[2]);
        });
      });
    }

    return out;
  }

  // FROM v2 line 20294-20310 — initial-load persist. Whitelisted snapshot
  // of the seeded prefill so OTHER sessions (different machine, different
  // user opening the same doc) skip the AI roundtrip even if the user
  // closes the modal without editing.
  var PREFILL_FIELDS = [
    "type", "agreement_type", "colgate_entity", "entity",
    "third_party_entity", "contact_full_name", "contact_email",
    "requester_name", "requester_email", "cp_ref",
    "additional_participants",
  ];
  function _persistInitialPrefill(prefill) {
    if (!prefill || typeof prefill !== "object") return;
    var snap = {};
    PREFILL_FIELDS.forEach(function (k) {
      var v = prefill[k];
      var keep = v != null && v !== "" && !(Array.isArray(v) && v.length === 0);
      if (keep) snap[k] = v;
    });
    if (!Object.keys(snap).length) return;
    try {
      var s = Office.context.document.settings;
      s.set("EliEmailerPrefill", snap);
      if (typeof s.saveAsync === "function") s.saveAsync(function () {});
    } catch (e) { /* tolerate */ }
  }

  // FROM v2 runAiEmailScanner Tier-3 fallback (line 20175-20239).
  // Word.run reads body + every section's headers + footers, sends the
  // combined text to Gemini with the v2 extraction prompt, returns the
  // parsed JSON or null. Caller is responsible for normalizing +
  // persisting. ~3-5s on a typical doc; gated by hasApiKey upstream.
  function _aiBodyScan() {
    if (!eli.host || typeof eli.host.runRaw !== "function") return Promise.resolve(null);
    if (!eli.ai || typeof eli.ai.completeJSON !== "function" || !eli.ai.hasApiKey()) return Promise.resolve(null);
    return eli.host.runRaw("auto_emailer:body_scan", function (context) {
      var body = context.document.body;
      var sections = context.document.sections;
      body.load("text");
      sections.load("items");
      return context.sync().then(function () {
        var ranges = [body];
        for (var i = 0; i < sections.items.length; i++) {
          var sec = sections.items[i];
          ["Primary", "FirstPage", "EvenPages"].forEach(function (kind) {
            try { ranges.push(sec.getFooter(kind)); } catch (e) {}
