          });
        }
        ranges.forEach(function (r) { try { r.load("text"); } catch (e) {} });
        return context.sync().then(function () {
          return ranges.map(function (r) { return r.text || ""; }).join("\n\n").trim().substring(0, 500000);
        });
      });
    }).then(function (docText) {
      if (!docText || docText.length < 40) return null;
      var prompt =
        "You are a Senior Legal Assistant. Extract metadata for an email cover letter.\n" +
        "TASK: Scan the document text below.\n" +
        "EXTRACT THESE SPECIFIC FIELDS:\n" +
        "1. Agreement Type (e.g. NDA, MSA, SOW).\n" +
        "2. Entities: Colgate or Hill's vs. The Third Party.\n" +
        "3. Contact Info: primary Third Party Contact (Name & Email) — usually in the Notices section or signature block.\n" +
        "4. Requester: the Colgate or Hill's employee requesting the agreement (Name & Email).\n" +
        "5. CP Ref #: look in headers/footers for 'CP Ref', 'Ref #', or codes like 'A-12345'.\n" +
        "RETURN RAW JSON (no markdown, no preamble):\n" +
        "{\n" +
        '  "type": "Agreement Type",\n' +
        '  "colgate_entity": "Colgate|Hills|CPSH",\n' +
        '  "third_party_entity": "Company Name",\n' +
        '  "contact_full_name": "Full Name",\n' +
        '  "contact_email": "email@address.com",\n' +
        '  "requester_name": "Colgate Employee",\n' +
        '  "requester_email": "employee@colpal.com",\n' +
        '  "cp_ref": "A-2025-12345-US"\n' +
        "}\n" +
        "Use empty string for any field not found.\n\n" +
        "DOCUMENT TEXT:\n" + docText;
      return eli.events.safeAsync(eli.ai.completeJSON(prompt, null, { maxTokens: 1500 }), "auto_emailer.body_scan")
        .catch(function () { return null; });
    }).catch(function () { return null; });
  }

  // Mirrors build_draft's _normalizeAiPrefill — same field map so both
  // tools converge on the same EliEmailerPrefill schema.
  function _normalizeScanResult(json) {
    if (!json || typeof json !== "object") return null;
    var ent = String(json.colgate_entity || json.entity || "").toLowerCase();
    return {
      type: json.type || "",
      third_party_entity: json.third_party_entity || "",
      cp_ref: json.cp_ref || "",
      contact_full_name: json.contact_full_name || "",
      contact_email: json.contact_email || "",
      requester_name: json.requester_name || "",
      requester_email: json.requester_email || "",
      entity: ent.indexOf("cpsh") !== -1 ? "CPSH" : ent.indexOf("hill") !== -1 ? "Hills" : (ent ? "Colgate" : ""),
    };
  }

  // FROM v2 runAiEmailScanner line 19992 — the "is this prefill useful
  // enough to skip AI?" check. Same 5 keys; any non-empty = useful.
  function _isPrefillUseful(p) {
    if (!p || typeof p !== "object") return false;
    return !!(p.third_party_entity || p.contact_email || p.requester_email || p.cp_ref || p.type);
  }

  // Open the composer. `seed` overrides doc-settings prefill (used when
  // build_draft hands off after save).
  function _open(seed) {
    if (!eli.ai || !eli.ai.hasApiKey()) {
      // Emailer doesn't directly call AI, but agreement_types data and
      // future AI-prefill paths assume the kernel is API-key-warm.
      // Keep this soft — open anyway, just with a hint.
      eli.log.event("tool", "auto_emailer_open_no_ai_key", {});
    }
    var mount = document.getElementById("_eli3_dashboard_root");
    var prefillBase = seed || _readDocPrefill();
    if (seed) {
      // Layer doc-settings on top for fields seed didn't populate
      // (typical: build_draft seeds entity/type/tp/ref but not contact/req).
      var stored = _readDocPrefill();
      ["contact_full_name", "contact_email", "requester_name", "requester_email", "additional_participants"]
        .forEach(function (k) {
          if (stored[k] && !prefillBase[k]) prefillBase[k] = stored[k];
        });
    }

    // FROM v2 line 20242-20251 — scrub MIME junk from type/agreement_type
    // before anything else uses these values.
    if (cleanAiPrefill) {
      var scrubResult = cleanAiPrefill(prefillBase);
      prefillBase = scrubResult.cleaned;
      if (scrubResult.scrubbed.length && typeof showToast === "function") {
        scrubResult.scrubbed.forEach(function (k) { showToast("🧹 Auto-cleaned: " + k, "info"); });
      }
    }

    // 2026-05-27: OARS-priority fill. Replaces the type-only check.
    // Agreement TYPE still overrides (user explicitly set it at OARS
    // load time). Every other field fills empty slots only — preserves
    // build_draft seed values that the user explicitly populated upstream.
    var oarsFill = _readOarsPrefill();
    if (oarsFill.type) {
      prefillBase.type = oarsFill.type;
      prefillBase.agreement_type = oarsFill.type;
    }
    var oarsFilledKeys = [];
    [
      "colgate_entity", "third_party_entity",
      "contact_full_name", "contact_email",
      "requester_name", "requester_email",
      "cp_ref",
    ].forEach(function (k) {
      if (oarsFill[k] && !prefillBase[k]) {
        prefillBase[k] = oarsFill[k];
        oarsFilledKeys.push(k);
      }
    });
    try {
      eli.log.event("tool", "auto_emailer_oars_prefill", {
        hadType: !!oarsFill.type,
        filledKeys: oarsFilledKeys,
        // Whether OARS gave us enough to skip the AI scan entirely.
        canSkipAi: !!(prefillBase.third_party_entity && prefillBase.cp_ref),
      });
    } catch (_e) {}

    // Default to Colgate entity when neither AI nor seed specified one.
    // FROM v2 line 20252-20259.
    if (!prefillBase.colgate_entity && !prefillBase.entity) {
      prefillBase.colgate_entity = "Colgate-Palmolive";
    }

    // FROM v2 runAiEmailScanner Tier 3 — AI body scan to fill missing
    // fields. Pre-2026-05-12 this only ran when prefillBase was almost
    // empty (skipped if ANY field was set). New rule: run AI whenever
    // the two core fields (third_party_entity, cp_ref) are missing,
    // even if seed has type/contact. AI fills only empty slots so
    // existing values (OARS type, build_draft seed) are preserved.
    var needsScan = !prefillBase.third_party_entity || !prefillBase.cp_ref;
    var prefillReady = !needsScan
      ? Promise.resolve(prefillBase)
      : (function () {
          if (typeof showToast === "function") showToast("🔍 Scanning doc for email fields…", "info");
          return _aiBodyScan().then(function (raw) {
            var extracted = _normalizeScanResult(raw);
            if (!extracted) return prefillBase;
            // Merge — only fill fields that are still empty in prefillBase
            // (preserves OARS type / explicit Colgate entity / build_draft
            // seed values that the user explicitly set upstream).
            Object.keys(extracted).forEach(function (k) {
              if (extracted[k] && !prefillBase[k]) prefillBase[k] = extracted[k];
            });
            return prefillBase;
          });
        })();

    prefillReady.then(function (finalPrefill) {
      // Persist the cleaned snapshot now (before user edits) so other
      // sessions can skip AI even if this one's closed without saving.
      _persistInitialPrefill(finalPrefill);
      _loadAndRender(finalPrefill, seed);
    });
  }

  // Shape IDB template rows + resolve myName/useFullName. myName is
