  // ── Admin CC/recipient rules (email-cc-rules.json) ──────────────────
  // Published from admin_email_rules → eli-data CDN. Read fresh at SEND
  // time so the latest fleet rule set applies. Local config row
  // `_email_cc_rules` is the cache; one CDN refresh per session writes
  // through to it. raw.githubusercontent (not jsdelivr): small,
  // frequently-republished — same freshness reasoning as the
  // bd-templates manifest (jsdelivr's edge cache lags 5-15 min).
  var _ccRulesInflight = null;
  function _ccRulesUrl() {
    function _ls(k) { try { return (eli.compat && eli.compat.lsGet) ? eli.compat.lsGet(k) : (typeof localStorage !== "undefined" ? localStorage.getItem(k) : null); } catch (_e) { return null; } }
    var repo = _ls("eli_github_repo") || "apndrewn/eli-data";
    var branch = _ls("eli_github_branch") || "main";
    return "https://raw.githubusercontent.com/" + repo + "/" + branch + "/email-cc-rules.json?t=" + Date.now();
  }
  function _syncCcRulesFromCdn() {
