    _ccRulesInflight = fetch(_ccRulesUrl(), { cache: "no-store" })
      .then(function (r) { return r.ok ? r.json() : null; })
      .then(function (j) {
        if (j && Array.isArray(j.rules)) {
          eli.events.safeAsync(eli.storage.put("config", { key: "_email_cc_rules", value: j }), "auto_emailer.cc_rules_cache");
          return j;
        }
        return null;
      })
      .catch(function (e) {
        eli.log.event("tool", "auto_emailer_cc_rules_sync_failed", { msg: e && e.message });
        return null;
      });
    return _ccRulesInflight;
  }
  // Resolve the rule set for an outgoing email: prefer a fresh CDN result
  // (capped at 3s so the Gmail-open click never hangs), else the local
  // cache, else null (engine treats null as "no rules → no-op").
  function _loadCcRules() {
    var localP = eli.events.safeAsync(eli.storage.get("config", "_email_cc_rules"), "auto_emailer.cc_rules_load")
      .then(function (row) { return (row && row.value && Array.isArray(row.value.rules)) ? row.value : null; })
      .catch(function () { return null; });
