    var capped = new Promise(function (resolve) {
      var done = false;
      cdnP.then(function (v) { if (!done) { done = true; resolve(v); } });
      setTimeout(function () { if (!done) { done = true; resolve(null); } }, 3000);
    });
    return Promise.all([localP, capped]).then(function (res) { return res[1] || res[0] || null; });
