        mount: mount,
        prefill: prefillBase,
        agTypes: agTypes,
        requesters: requesters,
        templates: templates,
        defaultDest: dest,
        executionMode: executionMode,
        fromBuildDraft: fromBuildDraft,
        autoSelectId: null,
        auditRunId: auditRunId,
      });
    });
  }

  function _renderWith(state) {
    renderComposer({
      mount: state.mount,
      prefill: state.prefill || {},
      agTypes: state.agTypes,
      requesters: state.requesters,
      defaultDest: state.defaultDest,
      autoSelectId: state.autoSelectId,
      matchAgTypeIndex: matchAgTypeIndex,
      formatParticipantsCcs: formatParticipantsCcs || function () { return ""; },
      onBack: function () {
        if (eli.dashboard && typeof eli.dashboard.goHome === "function") eli.dashboard.goHome();
        else if (eli.dashboard && typeof eli.dashboard.render === "function") eli.dashboard.render();
      },
      onPersistPrefill: _persistDocPrefill,
      onStripPrefill: function () {
        // FROM v2 _eliEmailerStripPrefill (line 20325). Removes the
        // entire EliEmailerPrefill entry from doc settings, then
        // re-renders the composer with empty prefill so EVERY visible
        // field clears (the previous version cleared just 4). Returns a
        // Promise that rejects on failure so the view can surface a real
        // error toast instead of a misleading "removed" success toast.
        return new Promise(function (resolve, reject) {
          try {
            var s = Office.context.document.settings;
            s.remove("EliEmailerPrefill");
            if (typeof s.saveAsync === "function") {
              s.saveAsync(function (res) {
                if (res && res.status !== Office.AsyncResultStatus.Succeeded) {
                  eli.log.event("tool", "auto_emailer_strip_save_failed", {
                    msg: res.error && res.error.message,
                  });
                  reject(new Error("Couldn't write doc settings: " +
                    (res.error && res.error.message || "unknown")));
                  return;
                }
                _afterStrip();
                resolve();
              });
            } else {
              _afterStrip();
              resolve();
            }
          } catch (e) {
            eli.log.event("tool", "auto_emailer_strip_failed", { msg: e && e.message });
            reject(e);
          }
        });
        function _afterStrip() {
          // Re-render with empty prefill so all fields + selects + collapsed
          // panels reset. Cleaner than patching individual inputs.
          state.prefill = {};
          state.autoSelectId = null;
          _renderWith(state);
        }
      },
      onSaveRequester: eli.events.guard(function (newReq) {
        var id = String(Date.now());
        var row = { id: id, name: newReq.name, email: newReq.email };
        eli.events.safeAsync(eli.storage.put("requesters", row), "auto_emailer.req_save").then(function () {
          if (typeof showToast === "function") showToast("✅ Requester saved", "ok");
          state.requesters = state.requesters.concat([row]);
          state.autoSelectId = id;
          _renderWith(state);
        });
      }, "auto_emailer.req_save_outer"),
      onDeleteRequester: function (id) {
        eli.ui.confirm({
          title: "Delete Requester?",
          message: "This removes them from your saved list permanently.",
          variant: "danger",
        }).then(function (ok) {
          if (!ok) return;
          eli.events.safeAsync(eli.storage.delete("requesters", id), "auto_emailer.req_del").then(function () {
            state.requesters = state.requesters.filter(function (r) { return String(r.id) !== String(id); });
            state.autoSelectId = null;
            if (typeof showToast === "function") showToast("🗑️ Removed", "ok");
            _renderWith(state);
          });
        });
      },
      onOpenGmail: function (form) {
        // Instrumented end-to-end — every step logs + a failure at any
        // step surfaces a toast instead of dying silently. Trace with
        // eli.debug(true): auto_emailer_gmail_step shows how far we got.
        eli.log.event("tool", "auto_emailer_gmail_step", { step: "click" });
        if (typeof showToast === "function") showToast("⏳ Preparing Gmail draft…", "ok");
        return _scanProtocolNumber().then(function (protocol) {
          eli.log.event("tool", "auto_emailer_gmail_step", { step: "scan_done", hasProtocol: !!protocol });
          form.protocol = protocol || "";
          // Forward execution-mode through to engine.buildGmailUrl so it
          // picks the FOR-SIGNATURE custom subject/body for TP emails.
          form.executionMode = !!state.executionMode;
          form.fromBuildDraft = !!state.fromBuildDraft;
