            try {
              url = buildGmailUrl(form, state.templates || shapeEmailTemplates([]));
            } catch (e) {
              eli.log.event("tool", "auto_emailer_buildurl_failed", { msg: e && e.message });
              if (typeof showToast === "function") showToast("Gmail URL build failed: " + (e && e.message || "unknown"), "err");
              return null;
            }
            eli.log.event("tool", "auto_emailer_gmail_step", { step: "url_built", urlLen: (url || "").length });
