              try { eli.bus.emit("build_draft:emailed", { runId: state.auditRunId }); } catch (_e) {}
            }
            return null;
          });
        }).catch(function (e) {
          eli.log.event("tool", "auto_emailer_gmail_chain_failed", { msg: e && e.message });
          if (typeof showToast === "function") showToast("Gmail draft failed: " + (e && e.message || "unknown"), "err");
          return null;
        });
      },
    });
  }

  // Word.run scan for [Protocol] token. FROM v2 line 20634-20668 —
  // body first, then per-section FirstPage + Primary headers. Returns ""
  // when no match (URL just has empty [Protocol] substitution).
  function _scanProtocolNumber() {
    if (!extractProtocol || !eli.host || !eli.host.runRaw) return Promise.resolve("");
    // Race the Word.run against a 6s timeout — a hung runRaw would
    // otherwise leave the chain (and the "Opening…" button) stuck
    // forever with no dialog. The [Protocol] token is optional, so a
    // timeout just yields "" — same as no match.
    var timeout = new Promise(function (resolve) {
      setTimeout(function () {
        eli.log.event("tool", "auto_emailer_protocol_scan_timeout", {});
        resolve("");
      }, 6000);
    });
    var scan = eli.host.runRaw("auto_emailer:protocol_scan", function (context) {
      var body = context.document.body;
      var sections = context.document.sections;
      body.load("text");
      sections.load("items");
      return context.sync().then(function () {
        var bodyHit = extractProtocol(body.text);
        if (bodyHit) return bodyHit;
        var headers = [];
        for (var i = 0; i < sections.items.length; i++) {
          ["FirstPage", "Primary"].forEach(function (kind) {
            try { headers.push(sections.items[i].getHeader(kind)); } catch (e) {}
          });
        }
        headers.forEach(function (r) { try { r.load("text"); } catch (e) {} });
        return context.sync().then(function () {
          for (var j = 0; j < headers.length; j++) {
            var hit = extractProtocol(headers[j].text || "");
            if (hit) return hit;
          }
          return "";
        });
      });
    }).catch(function (err) {
      eli.log.event("tool", "auto_emailer_protocol_scan_failed", { msg: err && err.message });
      return "";
    });
    return Promise.race([scan, timeout]);
  }

  function _openUrl(url, form) {
    _recordStatSafe("emailsDrafted");
    if (eli.activity && eli.activity.add) {
      eli.activity.add({
        type: "auto-emailer", icon: "✉️", label: "Auto Emailer · Draft",
        summary: "Drafted " + (form.dest === "req" ? "to requester" : "to TP") + " · " + (form.type || "?"),
        payload: { dest: form.dest, type: form.type, third_party: form.third_party_entity },
      });
    }
    // openBrowserWindow is gesture-independent — we arrive here from a
    // `.then()` after the async protocol-scan Word.run, so the user
    // gesture is gone and a bare window.open() / <a target=_blank> are
    // pop-up-blocked in Script Lab's sandbox. openBrowserWindow is the
    // one path that still works post-gesture; open directly with it.
    // Only when it's genuinely unavailable (or throws) do we fall back
    // to the manual dialog, whose buttons run inside a fresh click.
