      hasObw = !!(typeof Office !== "undefined" && Office.context && Office.context.ui &&
        typeof Office.context.ui.openBrowserWindow === "function");
    } catch (e) { hasObw = false; }
    eli.log.event("tool", "auto_emailer_gmail_step", {
      step: "open_url", urlLen: (url || "").length, hasObw: hasObw,
      hasDialog: typeof showEliDialog === "function",
    });
    if (hasObw) {
      try {
        Office.context.ui.openBrowserWindow(url);
        if (typeof showToast === "function") showToast("📧 Opening Gmail draft…", "ok");
        return;
      } catch (e) {
        eli.log.event("tool", "auto_emailer_obw_threw", { msg: e && e.message });
        // fall through to the manual dialog
      }
    }
    try {
      _showGmailLinkDialog(url, hasObw);
    } catch (e) {
      eli.log.event("tool", "auto_emailer_dialog_failed", { msg: e && e.message });
      try { navigator.clipboard.writeText(url); } catch (_) {}
      if (typeof showToast === "function") {
        showToast("Gmail link copied — dialog failed: " + (e && e.message || "unknown"), "warn");
      }
    }
  }

  // Manual-open fallback — used only when openBrowserWindow is missing
  // or threw. Every action runs inside a real click (fresh user
  // gesture), the only reliable way out of the Script Lab sandbox.
  function _showGmailLinkDialog(url, hasObw) {
    if (typeof showEliDialog !== "function") {
      try { navigator.clipboard.writeText(url); } catch (e) {}
      if (typeof showToast === "function") showToast("Gmail link copied — paste into your browser", "ok");
      return;
    }
    var body = document.createElement("div");
    var p = document.createElement("p");
    p.textContent = "Your pre-filled Gmail draft is ready. Open it in your browser, or copy the link and paste it into a new tab.";
    var urlBox = document.createElement("div");
    urlBox.textContent = url;
    urlBox.style.cssText = "margin-top:8px;padding:6px 8px;background:#f1f5f9;border:1px solid #cbd5e1;" +
      "font-size:10px;color:#475569;word-break:break-all;max-height:54px;overflow:auto;user-select:all;";
    body.appendChild(p);
    body.appendChild(urlBox);
    var buttons = [];
    buttons.push({
      label: "🌐 Open in Browser", cls: "btn-action btn-primary",
      onclick: function (e, ov) {
        var ok = false;
        // 1) openBrowserWindow inside a real click. 2) window.open
        // inside a real click (gesture often lets it through). 3) a
        // synthesised <a target=_blank> click.
        try {
          if (hasObw) { Office.context.ui.openBrowserWindow(url); ok = true; }
        } catch (e1) { ok = false; }
        if (!ok) { try { ok = !!window.open(url, "_blank", "noopener,noreferrer"); } catch (e2) { ok = false; } }
        if (!ok) {
          try {
            var a = document.createElement("a");
            a.href = url; a.target = "_blank"; a.rel = "noopener noreferrer";
            document.body.appendChild(a); a.click(); document.body.removeChild(a);
            ok = true;
          } catch (e3) { ok = false; }
        }
        if (ok) {
          if (typeof showToast === "function") showToast("Opening Gmail draft…", "ok");
          if (ov && ov.parentNode) ov.parentNode.removeChild(ov);
        } else {
          if (typeof showToast === "function") showToast("Couldn't open a window — use Copy link instead.", "warn");
        }
        return false; // we close it ourselves on success
      },
    });
    buttons.push({
      label: "📋 Copy link", cls: "btn-action btn-secondary",
      onclick: function () {
        var copied = false;
        try { navigator.clipboard.writeText(url); copied = true; } catch (e) { copied = false; }
        if (!copied) {
          try {
            var ta = document.createElement("textarea");
            ta.value = url; ta.style.cssText = "position:fixed;left:-9999px;";
            document.body.appendChild(ta); ta.select();
            copied = document.execCommand("copy");
            document.body.removeChild(ta);
          } catch (e) { copied = false; }
        }
        if (typeof showToast === "function") {
          showToast(copied ? "Link copied — paste into a browser tab" : "Copy failed — select the link text manually", copied ? "ok" : "err");
        }
        return false; // keep the dialog open
      },
    });
    buttons.push({ label: "Close", cls: "btn-action btn-secondary", onclick: function () {} });
    showEliDialog({ variant: "info", icon: "✉️", title: "Gmail Draft Ready", body: body, buttons: buttons });
  }

  // ─── Templates panel (gear icon) ──────────────────────────────────────
  // FROM v2 showConfigModal('email') (line 13833+). Edits the email
  // template subject + body for TP / Requester emails — both default and
  // per-agreement-type overrides — plus My Name / Use Full Name signature
  // settings. Persists to STORE_EMAIL_TEMPLATES with the same row shape
  // the engine's shapeEmailTemplates reads.
  function _openTemplatesPanel() {
    if (!renderTemplatesPanel) {
      if (typeof showToast === "function") showToast("Templates panel not loaded.", "warn");
      return;
    }
    var mount = document.getElementById("_eli3_dashboard_root");
    Promise.all([
      eli.events.safeAsync(eli.storage.getAll("agreement_types"), "auto_emailer.tmpl_ag_types"),
      eli.events.safeAsync(eli.storage.getAll("email_templates"), "auto_emailer.tmpl_load"),
    ]).then(function (results) {
      var agTypes = (results[0] || [])
        .filter(function (r) { return r && !r.pseudo; })
        .map(function (r) { return r.label || r.name || r.id; })
        .filter(Boolean);
      var templates = _shapeTemplatesWithName(results[1] || []);
      renderTemplatesPanel({
        mount: mount,
        templates: templates,
        agTypes: agTypes,
        onBack: function () {
          if (eli.dashboard && typeof eli.dashboard.goHome === "function") eli.dashboard.goHome();
          else if (eli.dashboard && typeof eli.dashboard.render === "function") eli.dashboard.render();
        },
        onSave: eli.events.guard(function (form) {
          _saveTemplates(form).then(function () {
            if (typeof showToast === "function") showToast("✅ Templates saved", "ok");
            if (eli.dashboard && typeof eli.dashboard.goHome === "function") eli.dashboard.goHome();
            else if (eli.dashboard && typeof eli.dashboard.render === "function") eli.dashboard.render();
          }).catch(function (err) {
            eli.log.event("tool", "auto_emailer_tmpl_save_failed", { msg: err && err.message });
            if (typeof showToast === "function") showToast("Save failed: " + (err && err.message), "err");
          });
        }, "auto_emailer.tmpl_save"),
      });
    });
  }

  // Persist the form back to IDB. Writes 4 rows mirroring v2's shape so
  // shapeEmailTemplates reads them back correctly. Also mirrors myName +
  // useFullName to v2's `eli_user_settings.emailTemplates` so the v2
  // kernel (or other v2-aware paths) see the same value.
  function _saveTemplates(form) {
    var rows = [
      { id: "thirdParty", subject: (form.thirdParty || {}).subject || "", body: (form.thirdParty || {}).body || "" },
      { id: "requester",  subject: (form.requester  || {}).subject || "", body: (form.requester  || {}).body || "" },
      { id: "byType",     byType: form.byType || {} },
      { id: "settings",   myName: form.myName || "", useFullName: !!form.useFullName },
    ];
    var ops = rows.map(function (r) {
      return eli.storage.put("email_templates", r);
    });
    // Mirror to v2 localStorage. Best-effort — never block save on failure.
    try {
      var raw = eli.compat.lsGet("eli_user_settings");
      var s = {};
      if (raw) { try { s = JSON.parse(raw) || {}; } catch (e) { s = {}; } }
      if (!s.emailTemplates) s.emailTemplates = {};
      s.emailTemplates.myName = form.myName || "";
      s.emailTemplates.useFullName = !!form.useFullName;
      eli.compat.lsSet("eli_user_settings", JSON.stringify(s));
    } catch (e) {
      eli.log.event("tool", "auto_emailer_v2_settings_mirror_failed", { msg: e && e.message });
    }
    return Promise.all(ops);
  }

  // Register channels:
  //   tile / app_auto_emailer       — main click from dashboard
  //   tile_settings / app_auto_emailer — gear icon → templates editor
  //   auto_emailer:compose          — programmatic launch with a seed
  //                                    payload (used by build_draft post-save)
  eli.register({
    tile: { app_auto_emailer: function () {
      _recordStatSafe("appOpenedAutoEmailer");
      _open(null);
    } },
    tile_settings: { app_auto_emailer: function () {
      _recordStatSafe("appOpenedAutoEmailerTemplates");
      _openTemplatesPanel();
    } },
    // 2026-05-18 v48: NO stat record here — `compose` is fired by
    // build_draft after every successful save (init.js:2267), which
    // inflated appOpenedAutoEmailer on every Build Draft run rather
    // than counting only user-initiated tile clicks.
    auto_emailer: { compose: function (seed) {
      _open(seed || null);
    } },
  });

  // Pre-warm the CC rule set so the first send of the session applies
  // the freshest fleet rules without waiting on the network at click time.
  try { _syncCcRulesFromCdn(); } catch (_e) {}

  eli.log.event("tool", "auto_emailer_initialized", {});
}

jsonTools.css:
/* auto_emailer tool styles. Injected as <style data-tool="auto_emailer">. */

._eli3_ae_root {
  display: flex; flex-direction: column;
  width: 100%; height: 100%;
  background: #fff;
  overflow: hidden;
  box-sizing: border-box;
}
/* Standard tool-hub header — dark navy banner with gold accent rule. */
._eli3_ae_bar {
  flex: 0 0 auto;
  display: flex; align-items: center; gap: 10px;
  padding: 12px 14px;
  background: linear-gradient(135deg, #0d1b2a 0%, #1b263b 100%);
  border-bottom: 3px solid #c9a227;
}
._eli3_ae_back {
  background: none; border: none; cursor: pointer;
  font: 400 22px/1 'Inter', sans-serif; color: #cbd5e1;
  padding: 0 4px;
  transition: color 0.15s;
}
._eli3_ae_back:hover { color: #f2d866; }
._eli3_ae_title {
  flex: 1;
  font: 800 16px/1.2 'Georgia', serif;
  color: #ffffff;
  letter-spacing: 0.2px;
  /* 2026-05-26: flex layout so the index-status dot (and the mode
     slot when admin's eli_agent is installed) vertically center on
     the cap height of the serif text instead of riding the baseline.
     Without this, vertical-align:middle on the inline-block dot lands
     it noticeably below the optical center of "Ask ELI". */
  display: flex;
  align-items: center;
  gap: 6px;
}

/* Form body */
._eli3_ae_form {
  flex: 1 1 auto;
  overflow-y: auto;
  padding: 14px;
  display: flex; flex-direction: column; gap: 6px;
}
._eli3_ae_label {
  font: 700 11px/1.2 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.4px;
  color: #0f172a;
  margin-top: 6px;
}
._eli3_ae_input {
  width: 100%;
  padding: 8px 10px;
  border: 1px solid #cbd5e1;
  background: #fff;
  font: 500 13px/1.3 'Inter', sans-serif;
  color: #0f172a;
  box-sizing: border-box;
  outline: none;
}
._eli3_ae_input:focus {
  border-color: #1565c0;
  box-shadow: 0 0 0 2px rgba(21, 101, 192, 0.18);
}
._eli3_ae_grid2 {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

/* Destination (TP / Requester) toggle */
._eli3_ae_dest {
  display: flex; gap: 18px;
  padding: 10px 12px;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  margin-bottom: 6px;
}
._eli3_ae_dest_opt {
  display: inline-flex; align-items: center; gap: 6px;
  font: 600 12px/1 'Inter', sans-serif;
  color: #1e293b;
  cursor: pointer;
}
._eli3_ae_dest_opt input[type="radio"] {
  margin: 0; accent-color: #1565c0;
}

/* Requester picker box */
._eli3_ae_req_box {
  margin-top: 10px;
  padding: 10px 12px;
  background: #eff6ff;
  border: 1px solid #93c5fd;
}
._eli3_ae_req_head {
  display: flex; justify-content: space-between; align-items: center;
  margin-bottom: 6px;
  font: 700 10px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.5px;
  color: #1565c0;
}
._eli3_ae_req_del {
  background: none; border: none;
  color: #c62828;
  font: 700 9px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.4px;
  cursor: pointer;
}
._eli3_ae_req_del:hover { color: #8e1d1d; text-decoration: underline; }
._eli3_ae_req_manual {
  margin-top: 10px;
  padding-top: 10px;
  border-top: 1px dashed #93c5fd;
  display: flex; flex-direction: column; gap: 6px;
}
._eli3_ae_req_manual_btns {
  display: flex; gap: 8px;
  margin-top: 4px;
}
._eli3_ae_req_manual_btns ._eli3_ae_skip { flex: 1; }

/* Add Participants toggle (closed state) — small inline link. */
._eli3_ae_addcc_toggle {
  margin-top: 10px;
  font: 700 10px/1.2 'Inter', sans-serif;
  color: #1565c0;
  cursor: pointer;
  display: inline-block;
  user-select: none;
}
._eli3_ae_addcc_toggle:hover { color: #0d47a1; text-decoration: underline; }

/* Open state — green box matching v2 line 20411 (#f1f8e9 / #c5e1a5). */
._eli3_ae_addcc_box {
  margin-top: 10px;
  padding: 10px 12px;
  background: #f1f8e9;
  border: 1px solid #c5e1a5;
}

/* CCs textarea */
._eli3_ae_ccs {
  font-family: 'JetBrains Mono', monospace;
  height: 56px;
  resize: vertical;
}
._eli3_ae_hint {
  font: 400 10px/1 'Inter', sans-serif;
  color: #94a3b8;
  text-transform: none;
  letter-spacing: 0;
  margin-left: 4px;
}

/* Action row — Skip / Open Gmail Draft */
._eli3_ae_actions {
  display: flex;
  gap: 8px;
  margin-top: 14px;
}
._eli3_ae_skip {
  flex: 1;
  background: linear-gradient(180deg, #fff 0%, #f1f5f9 100%);
  border: 1px solid #cbd5e1;
  font: 700 11px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.4px;
  color: #475569;
  padding: 10px 14px;
  cursor: pointer;
  transition: all 0.15s;
}
._eli3_ae_skip:hover {
  background: linear-gradient(180deg, #f8fafc 0%, #e2e8f0 100%);
  color: #0f172a;
  border-color: #94a3b8;
}
._eli3_ae_btn {
  flex: 1.6;
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  background: linear-gradient(135deg, #1565c0 0%, #0d47a1 100%);
  color: #fff;
  border: 1px solid #0d47a1;
  font: 700 12px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.5px;
  padding: 10px 14px;
  cursor: pointer;
  transition: all 0.15s;
  box-shadow: 0 2px 6px rgba(21, 101, 192, 0.25);
}
._eli3_ae_btn:hover:not(:disabled) {
  background: linear-gradient(135deg, #1d4ed8 0%, #1565c0 100%);
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(21, 101, 192, 0.35);
}
._eli3_ae_btn:disabled { opacity: 0.6; cursor: progress; }
._eli3_ae_btn_icon { font-size: 14px; line-height: 1; }
._eli3_ae_btn_label { white-space: nowrap; }

/* =====================================================================
   Templates editor (renderTemplatesPanel)
   ===================================================================== */
._eli3_ae_tmpl_typebox {
  margin-top: 12px;
  padding: 10px 12px;
  background: #fff8e1;
  border: 1px solid #ffe082;
}
._eli3_ae_tmpl_hint {
  font: 500 10px/1.4 'Inter', sans-serif;
  color: #7a5d2a;
  font-style: italic;
  margin-top: 6px;
}
._eli3_ae_tmpl_block {
  margin-top: 12px;
  padding: 12px;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
}
._eli3_ae_tmpl_block_req {
  background: #eff6ff;
  border-color: #93c5fd;
}
._eli3_ae_tmpl_block_head {
  font: 700 11px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: #37474f;
  padding-bottom: 5px;
  margin-bottom: 8px;
  border-bottom: 1px solid #cbd5e1;
}
._eli3_ae_tmpl_block_req ._eli3_ae_tmpl_block_head {
  color: #1565c0;
  border-bottom-color: #93c5fd;
}
._eli3_ae_tmpl_textarea {
  height: 110px;
  font-family: 'Inter', sans-serif;
  line-height: 1.45;
  resize: vertical;
}
._eli3_ae_tmpl_resetrow {
  margin-top: 8px;
  display: flex;
  justify-content: flex-end;
}
._eli3_ae_tmpl_reset {
  flex: 0 0 auto;
}
._eli3_ae_tmpl_tokens {
  margin-top: 12px;
  padding: 8px 10px;
  background: #f1f5f9;
  border: 1px solid #cbd5e1;
  font: 600 10px/1.5 'JetBrains Mono', monospace;
  color: #475569;
}

/* Strip-prefill button — small inline link in the CP Ref label row. */
._eli3_ae_label_row {
  display: flex; align-items: center; justify-content: space-between;
  gap: 10px;
}
._eli3_ae_strip_prefill {
  background: none; border: none; cursor: pointer;
  font: 700 9px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.4px;
  color: #c62828;
  padding: 0 4px;
  transition: color 0.15s;
}
._eli3_ae_strip_prefill:hover {
  color: #8e1d1d;
  text-decoration: underline;
}
